// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

// --- INTERFACES ---
interface IERC20 {
    function transfer(
        address recipient,
        uint256 amount
    ) external returns (bool);

    function transferFrom(
        address sender,
        address recipient,
        uint256 amount
    ) external returns (bool);

    function balanceOf(address account) external view returns (uint256);
}

// --- SAFE ERC20 LIBRARY ---
// Protects against non-standard ERC20 tokens that don't return a boolean
library SafeERC20 {
    function safeTransfer(IERC20 token, address to, uint256 value) internal {
        (bool success, bytes memory data) = address(token).call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, value)
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "SafeERC20: transfer failed"
        );
    }

    function safeTransferFrom(
        IERC20 token,
        address from,
        address to,
        uint256 value
    ) internal {
        (bool success, bytes memory data) = address(token).call(
            abi.encodeWithSelector(
                IERC20.transferFrom.selector,
                from,
                to,
                value
            )
        );
        require(
            success && (data.length == 0 || abi.decode(data, (bool))),
            "SafeERC20: transferFrom failed"
        );
    }
}

contract TonsageMatrix {
    using SafeERC20 for IERC20;

    // --- SECURITY: REENTRANCY GUARD ---
    uint256 private currentTxId = 1;
    bool private locked;
    modifier nonReentrant() {
        require(!locked, "Reentrant call detected");
        locked = true;
        currentTxId++;
        _;
        locked = false;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this");
        _;
    }

    // --- STRUCTS ---
    struct UserIncome {
        uint256 globalBaseEarned;
        uint256 globalSpillEarned;
        uint256 levelBaseEarned;
        uint256 levelDirectBonus;
        uint256 totalEarned;
    }

    struct User {
        uint256 id;
        address referrer;
        uint256 directCount; // Valid directs (paid for Slot 1)
        address[] directReferrals;
        bool isActive;
        UserIncome income;
        mapping(uint8 => bool) activeGlobalSlots; // Tracks purchased Global slots
        mapping(uint8 => bool) activeLevelSlots; // Tracks purchased Level slots
    }

    struct GlobalCycle {
        address currentUpline;
        address[] spots; // Max 14
        uint256 upgradeHoldings;
        bool isCompleted;
    }

    struct LevelCycle {
        address currentUpline;
        address[] spots; // Max 14
        uint256 reentryHoldings;
        bool isCompleted;
    }

    struct MatrixState {
        uint256 currentGlobalCycle;
        uint256 currentLevelCycle;
        uint256 lastPaidDirectIndex;
        mapping(uint256 => GlobalCycle) globalCycles;
        mapping(uint256 => LevelCycle) levelCycles;
    }

    // --- STATE VARIABLES ---
    mapping(address => User) public users;
    mapping(uint256 => address) public idToAddress;
    mapping(address => mapping(uint8 => MatrixState)) public userMatrices;
    mapping(uint8 => uint256) public slotPrices;
    mapping(address => mapping(uint8 => mapping(uint256 => mapping(address => uint256))))
        public lastPlacedTx;
    mapping(address => uint256) public sponsorRoyaltyContribution;
    mapping(uint256 => uint256) public dailyRoyaltyCollection;

    address public companyWallet;
    mapping(address => bool) public isCompanyNode;

    uint256 public nextUserId = 1;
    uint8 public constant LAST_SLOT = 15;
    uint8 public constant MATRIX_SIZE = 14;

    address public owner;
    address public royalPoolWallet;
    address public liquidityWallet;
    address public treasuryWallet;
    IERC20 public WTON_TOKEN;
    bool private isDeploying = true;

    // --- EVENTS ---
    event UserRegistered(
        uint256 indexed userId,
        address indexed user,
        address indexed referrer
    );
    event SlotPurchased(
        address indexed user,
        uint8 slot,
        uint256 amount,
        string matrixType
    );
    event PlacedInGlobalMatrix(
        address indexed user,
        address indexed upline,
        uint8 slot,
        uint256 cycle,
        uint8 spotIndex
    );
    event PlacedInLevelMatrix(
        address indexed user,
        address indexed upline,
        uint8 slot,
        uint256 cycle,
        uint8 spotIndex
    );
    event EarningsSent(
        address indexed receiver,
        address indexed fromUser,
        uint256 amount,
        uint8 slot,
        string earningType
    );
    event MatrixRecycled(
        address indexed user,
        uint8 slot,
        uint256 newCycle,
        string matrixType
    );
    event AutoUpgraded(address indexed user, uint8 newSlot);
    event FundsWithheld(
        address indexed fromUser,
        address indexed matrixOwner,
        uint8 slot,
        uint256 amount,
        string reason
    );
    event RoyaltyContributed(
        address indexed sponsor,
        address indexed buyer,
        uint256 amount,
        uint256 dayId
    );
    event OwnershipTransferred(
        address indexed previousOwner,
        address indexed newOwner
    );

    // --- CONSTRUCTOR ---
    constructor(
        address _wton,
        address _royalPool,
        address _liquidityWallet,
        address _treasuryWallet
    ) {
        require(
            _wton != address(0) &&
                _royalPool != address(0) &&
                _liquidityWallet != address(0) &&
                _treasuryWallet != address(0),
            "Invalid addresses"
        );

        owner = msg.sender;
        WTON_TOKEN = IERC20(_wton);
        royalPoolWallet = _royalPool;
        liquidityWallet = _liquidityWallet;
        treasuryWallet = _treasuryWallet;

        // Initialize Slot Prices (Slot 1 = 2 WTON, doubles each slot)
        slotPrices[1] = 2 * 10 ** 9;
        for (uint8 i = 2; i <= LAST_SLOT; i++) {
            slotPrices[i] = slotPrices[i - 1] * 2;
        }

        // Setup Owner Profile (ID 1)
        User storage ownerProfile = users[owner];
        ownerProfile.id = nextUserId;
        ownerProfile.referrer = address(0);
        ownerProfile.directCount = 0;
        ownerProfile.isActive = true;

        for (uint8 i = 1; i <= LAST_SLOT; i++) {
            ownerProfile.activeGlobalSlots[i] = true;
            ownerProfile.activeLevelSlots[i] = true;
        }

        idToAddress[nextUserId] = owner;
        nextUserId++;

        isDeploying = false;
    }

    function setCompanyWallet(address _newWallet) external onlyOwner {
        require(_newWallet != address(0), "Cannot be zero address");
        companyWallet = _newWallet;
    }

    function setCompanyNodeStatus(
        address _node,
        bool _isCompany
    ) external onlyOwner {
        require(_node != address(0), "Cannot be zero address");
        isCompanyNode[_node] = _isCompany;
    }

    function renounceOwnership() external onlyOwner {
        emit OwnershipTransferred(owner, address(0));
        owner = address(0);
    }

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "New owner cannot be zero address");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }

    function setupPromoLeader(address leader) external onlyOwner {
        require(leader != address(0), "Invalid leader address");
        require(users[leader].id == 0, "Leader already registered");

        // 1. Register under owner
        User storage newLeader = users[leader];
        newLeader.id = nextUserId;
        newLeader.referrer = owner;
        users[owner].directReferrals.push(leader);
        newLeader.directCount = 0;
        newLeader.isActive = true;

        idToAddress[nextUserId] = leader;
        nextUserId++;
        users[owner].directCount++;

        emit UserRegistered(newLeader.id, leader, owner);

        // 2. Temporarily disable physical token transfers
        isDeploying = true;

        // 3. Loop through ALL 15 slots and place them in the matrices
        for (uint8 slot = 1; slot <= LAST_SLOT; slot++) {
            newLeader.activeGlobalSlots[slot] = true;
            newLeader.activeLevelSlots[slot] = true;

            emit SlotPurchased(
                leader,
                slot,
                0,
                "TON Titan & TON Infinity (Promo)"
            );

            _placeInGlobalMatrix(leader, owner, slot);
            _placeInLevelMatrix(leader, owner, slot);
        }

        // 4. Turn token transfers back on!
        isDeploying = false;
    }

    function syncUser(address user, address referrer) external onlyOwner {
        require(users[user].id == 0, "User already registered");
        require(
            users[referrer].id != 0 || referrer == owner,
            "Invalid referrer"
        );

        User storage newUser = users[user];
        newUser.id = nextUserId;
        newUser.referrer = referrer;
        users[referrer].directReferrals.push(user);
        newUser.directCount = 0;
        newUser.isActive = false; // Remains false until Slot 1 is purchased

        idToAddress[nextUserId] = user;
        nextUserId++;

        emit UserRegistered(newUser.id, user, referrer);
    }

    function syncSlot(address user, uint8 slot) external onlyOwner {
        require(users[user].id != 0, "User must be registered first");
        require(slot >= 1 && slot <= LAST_SLOT, "Invalid slot");

        // 🛑 Pause physical token transfers and income tracking during migration
        isDeploying = true;

        if (slot == 1) {
            require(!users[user].activeGlobalSlots[1], "Slot 1 already active");

            // Activate User Profile
            users[user].isActive = true;
            users[user].activeGlobalSlots[1] = true;
            users[user].activeLevelSlots[1] = true;

            // Increment sponsor direct count
            address referrer = users[user].referrer;
            if (referrer != address(0)) {
                users[referrer].directCount++;
            }

            emit SlotPurchased(user, 1, 0, "Migration: TON Titan & Infinity");

            // Place in both matrices
            _placeInGlobalMatrix(user, _findGlobalUpline(user, 1), 1);
            _placeInLevelMatrix(user, _findLevelUpline(user, 1), 1);
        } else {
            // For slots 2-15 (Level Matrix / TON Infinity only)
            require(!users[user].activeLevelSlots[slot], "Slot already active");
            require(
                users[user].activeLevelSlots[slot - 1],
                "Must buy previous slot first"
            );

            // Activate Level Slot
            users[user].activeLevelSlots[slot] = true;

            emit SlotPurchased(user, slot, 0, "Migration: TON Infinity Only");

            // Place ONLY in Level Matrix
            _placeInLevelMatrix(user, _findLevelUpline(user, slot), slot);
        }

        isDeploying = false;
    }

    // --- BUBBLE UP HELPER FUNCTIONS ---

    function _peekQualifiedDirect(
        address matrixOwner,
        uint8 slot
    ) internal view returns (address) {
        address[] memory directs = users[matrixOwner].directReferrals;
        uint256 totalDirects = directs.length;

        if (totalDirects == 0) return address(0);

        uint256 startIndex = userMatrices[matrixOwner][slot]
            .lastPaidDirectIndex;

        // LIMIT TO 50 CHECKS TO PREVENT OUT OF GAS ERRORS
        uint256 maxChecks = totalDirects > 50 ? 50 : totalDirects;

        for (uint256 i = 0; i < maxChecks; i++) {
            uint256 currentIndex = (startIndex + i) % totalDirects;
            address direct = directs[currentIndex];

            if (
                users[direct].activeGlobalSlots[slot] &&
                _hasActiveDirect(direct, slot)
            ) {
                return direct;
            }
        }
        return address(0);
    }

    function _getQualifiedDirect(
        address matrixOwner,
        uint8 slot
    ) internal returns (address) {
        address[] memory directs = users[matrixOwner].directReferrals;
        uint256 totalDirects = directs.length;

        if (totalDirects == 0) return address(0);

        uint256 startIndex = userMatrices[matrixOwner][slot]
            .lastPaidDirectIndex;
        uint256 currentIndex;

        // LIMIT TO 50 CHECKS TO PREVENT OUT OF GAS ERRORS
        uint256 maxChecks = totalDirects > 50 ? 50 : totalDirects;

        for (uint256 i = 0; i < maxChecks; i++) {
            currentIndex = (startIndex + i) % totalDirects;
            address direct = directs[currentIndex];

            if (
                users[direct].activeGlobalSlots[slot] &&
                _hasActiveDirect(direct, slot)
            ) {
                userMatrices[matrixOwner][slot].lastPaidDirectIndex =
                    (currentIndex + 1) %
                    totalDirects;

                return direct;
            }
        }

        // If no one is found within the limit, increment index by the amount checked so it searches the next batch next time
        userMatrices[matrixOwner][slot].lastPaidDirectIndex =
            (startIndex + maxChecks) %
            totalDirects;
        return address(0);
    }

    function _getLevelReceivers(
        address upline,
        uint8 slot,
        uint256 cycle,
        uint8 spotIndex
    ) internal view returns (address l1, address l2, address l3) {
        LevelCycle storage matrix = userMatrices[upline][slot].levelCycles[
            cycle
        ];

        if (spotIndex == 0 || spotIndex == 1) {
            l1 = upline;
            l2 = matrix.currentUpline;
            if (l2 != address(0)) {
                // FIX: Find the correct cycle for L3 payout routing
                uint256 l2Cycle = userMatrices[l2][slot].currentLevelCycle;
                while (true) {
                    if (_findUserIndex(l2, slot, l2Cycle, upline) != -1) break;
                    if (l2Cycle == 0) break;
                    l2Cycle--;
                }
                l3 = userMatrices[l2][slot].levelCycles[l2Cycle].currentUpline;
            }
        } else if (spotIndex >= 2 && spotIndex <= 5) {
            l1 = matrix.spots[(spotIndex - 2) / 2];
            l2 = upline;
            l3 = matrix.currentUpline;
        } else if (spotIndex >= 6 && spotIndex <= 13) {
            l1 = matrix.spots[(spotIndex - 2) / 2];
            l2 = matrix.spots[(spotIndex - 6) / 4];
            l3 = upline;
        }
    }

    function _isUserInLevelCycle(
        address upline,
        uint8 slot,
        uint256 cycle,
        address target
    ) internal view returns (bool) {
        address[] memory spots = userMatrices[upline][slot]
            .levelCycles[cycle]
            .spots;
        for (uint8 i = 0; i < spots.length; i++) {
            if (spots[i] == target) return true;
        }
        return false;
    }

    // 1. Finds exactly where a user is sitting in their upline's array
    function _findUserIndex(
        address upline,
        uint8 slot,
        uint256 cycle,
        address target
    ) internal view returns (int8) {
        address[] memory spots = userMatrices[upline][slot]
            .levelCycles[cycle]
            .spots;
        for (uint8 i = 0; i < spots.length; i++) {
            if (spots[i] == target) return int8(i);
        }
        return -1;
    }

    function _findLatestUserIndex(
        address upline,
        uint8 slot,
        uint256 cycle,
        address target
    ) internal view returns (int8) {
        address[] memory spots = userMatrices[upline][slot]
            .levelCycles[cycle]
            .spots;

        if (spots.length == 0) return -1;

        for (int8 i = int8(uint8(spots.length)) - 1; i >= 0; i--) {
            if (spots[uint8(i)] == target) return i;
        }
        return -1;
    }

    // 2. Dynamically pads the array with empty spaces so users land in the exact visual box
    function _placeAtSpecificIndexLevel(
        address upline,
        uint8 slot,
        uint256 cycle,
        uint8 targetIndex,
        address user
    ) internal {
        LevelCycle storage matrix = userMatrices[upline][slot].levelCycles[
            cycle
        ];

        // If the array is too short, pad it with zero addresses to create the "gaps"
        while (matrix.spots.length <= targetIndex) {
            matrix.spots.push(address(0));
        }

        // Lock the user into their exact visual spot
        matrix.spots[targetIndex] = user;
    }

    function _padAndPlaceLevel(
        address upline,
        uint8 slot,
        address user,
        uint8 targetIndex
    ) internal {
        uint256 cycle = userMatrices[upline][slot].currentLevelCycle;
        LevelCycle storage matrix = userMatrices[upline][slot].levelCycles[
            cycle
        ];

        while (matrix.spots.length <= targetIndex) {
            matrix.spots.push(address(0));
        }
        matrix.spots[targetIndex] = user;
    }

    function _padAndPlaceLevelAtCycle(
        address upline,
        uint8 slot,
        uint256 cycle,
        address user,
        uint8 targetIndex
    ) internal {
        LevelCycle storage matrix = userMatrices[upline][slot].levelCycles[
            cycle
        ];

        while (matrix.spots.length <= targetIndex) {
            matrix.spots.push(address(0));
        }
        matrix.spots[targetIndex] = user;
    }

    // --- EXTERNAL FUNCTIONS (PURCHASES) ---

    // 1. FREE REGISTRATION: Creates profile, but user remains "inactive"
    function register(address referrer) external nonReentrant {
        require(users[msg.sender].id == 0, "Already registered");
        require(
            users[referrer].id != 0 || referrer == owner,
            "Invalid referrer"
        );

        User storage newUser = users[msg.sender];
        newUser.id = nextUserId;
        newUser.referrer = referrer;
        users[referrer].directReferrals.push(msg.sender);
        newUser.directCount = 0;
        newUser.isActive = false; // Remains false until Slot 1 is purchased

        idToAddress[nextUserId] = msg.sender;
        nextUserId++;

        emit UserRegistered(users[msg.sender].id, msg.sender, referrer);
    }

    // 2. FIRST PURCHASE (4.8 WTON): Activates Global & Level Matrix Slot 1
    function buySlot1() external nonReentrant {
        require(users[msg.sender].id != 0, "Must register first");
        require(
            !users[msg.sender].activeGlobalSlots[1],
            "Slot 1 already active"
        );

        uint256 globalCost = slotPrices[1];
        uint256 levelCost = slotPrices[1];
        uint256 totalBaseCost = globalCost + levelCost; // 4 WTON
        uint256 royalFee = (totalBaseCost * 20) / 100; // 0.8 WTON
        uint256 totalCost = totalBaseCost + royalFee; // 4.8 WTON total

        // Pull Tokens & Pay Royal Pool (USING SAFE TRANSFER)
        WTON_TOKEN.safeTransferFrom(msg.sender, address(this), totalCost);
        WTON_TOKEN.safeTransfer(royalPoolWallet, royalFee);

        address sponsor = users[msg.sender].referrer;
        if (sponsor != address(0)) {
            sponsorRoyaltyContribution[sponsor] += royalFee;
            uint256 currentDay = getCurrentDay();
            dailyRoyaltyCollection[currentDay] += royalFee;

            emit RoyaltyContributed(sponsor, msg.sender, royalFee, currentDay);
        }

        emit EarningsSent(
            royalPoolWallet,
            msg.sender,
            royalFee,
            1,
            "Royalty Fee"
        );

        // Activate User Profile
        users[msg.sender].isActive = true;
        users[msg.sender].activeGlobalSlots[1] = true;
        users[msg.sender].activeLevelSlots[1] = true;

        // Security Rule: Only increment direct count upon successful payment
        address referrer = users[msg.sender].referrer;
        if (referrer != address(0)) {
            users[referrer].directCount++;
        }

        emit SlotPurchased(
            msg.sender,
            1,
            totalCost,
            "TON Titan & TON Infinity"
        );

        // Place in both matrices
        _placeInGlobalMatrix(msg.sender, _findGlobalUpline(msg.sender, 1), 1);
        _placeInLevelMatrix(msg.sender, _findLevelUpline(msg.sender, 1), 1);
    }

    function getRoyaltyForPastDays(
        uint256 daysToCalculate
    ) external view returns (uint256 total) {
        require(daysToCalculate > 0, "Must calculate at least 1 day");

        uint256 currentDay = getCurrentDay();

        for (uint256 i = 0; i < daysToCalculate; i++) {
            // Safety Check: Prevent underflow if you ask for more days than the blockchain has existed
            if (currentDay < i) {
                break;
            }

            total += dailyRoyaltyCollection[currentDay - i];
        }

        return total;
    }

    // 3. MANUAL LEVEL PURCHASES: For Level Matrix slots 2 through 12
    function buyLevelSlot(uint8 slot) external nonReentrant {
        require(users[msg.sender].id != 0, "Must register first");
        require(slot > 1 && slot <= LAST_SLOT, "Invalid slot");
        require(
            !users[msg.sender].activeLevelSlots[slot],
            "Slot already active"
        );
        require(
            users[msg.sender].activeLevelSlots[slot - 1],
            "Must buy previous infinity slot first"
        );

        uint256 slotCost = slotPrices[slot];
        uint256 royalFee = (slotCost * 20) / 100;
        uint256 totalCost = slotCost + royalFee;

        // Pull Tokens & Pay Royal Pool (USING SAFE TRANSFER)
        WTON_TOKEN.safeTransferFrom(msg.sender, address(this), totalCost);
        WTON_TOKEN.safeTransfer(royalPoolWallet, royalFee);

        address sponsor = users[msg.sender].referrer;
        if (sponsor != address(0)) {
            sponsorRoyaltyContribution[sponsor] += royalFee;
            uint256 currentDay = getCurrentDay();
            dailyRoyaltyCollection[currentDay] += royalFee;

            emit RoyaltyContributed(sponsor, msg.sender, royalFee, currentDay);
        }

        emit EarningsSent(
            royalPoolWallet,
            msg.sender,
            royalFee,
            slot,
            "Royalty Fee"
        );
        // Activate Level Slot
        users[msg.sender].activeLevelSlots[slot] = true;

        emit SlotPurchased(msg.sender, slot, totalCost, "TON Infinity Only");

        // Place ONLY in Level Matrix
        _placeInLevelMatrix(
            msg.sender,
            _findLevelUpline(msg.sender, slot),
            slot
        );
    }

    function _hasActiveDirect(
        address user,
        uint8 slot
    ) internal view returns (bool) {
        address[] memory directs = users[user].directReferrals;
        for (uint256 i = 0; i < directs.length; i++) {
            if (users[directs[i]].activeGlobalSlots[slot]) {
                return true; // Found at least one qualified direct for this exact slot!
            }
        }
        return false;
    }

    function getCurrentDay() public view returns (uint256) {
        return block.timestamp / 86400; // Returns the unique index for the current day
    }

    // --- INTERNAL MATRIX PLACEMENT ---

    function _isUserInGlobalCycle(
        address upline,
        uint8 slot,
        uint256 cycle,
        address target
    ) internal view returns (bool) {
        address[] memory spots = userMatrices[upline][slot]
            .globalCycles[cycle]
            .spots;
        for (uint8 i = 0; i < spots.length; i++) {
            if (spots[i] == target) return true;
        }
        return false;
    }

    // 1. GLOBAL MATRIX (Strict Placement / Payment Based)
    function _placeInGlobalMatrix(
        address user,
        address upline,
        uint8 slot
    ) internal {
        // Prevent infinite loops at the very top
        if (upline == address(0)) upline = owner;

        uint256 cycle = userMatrices[upline][slot].currentGlobalCycle;
        GlobalCycle storage matrix = userMatrices[upline][slot].globalCycles[
            cycle
        ];

        if (lastPlacedTx[upline][slot][cycle][user] == currentTxId) {
            // Push them one level higher to break the infinite loop!
            address nextUpline = _findGlobalUpline(upline, slot);

            // Anti-loop failsafe
            if (nextUpline != upline && nextUpline != user) {
                _placeInGlobalMatrix(user, nextUpline, slot);
            }
            return;
        }

        lastPlacedTx[upline][slot][cycle][user] = currentTxId;

        uint8 spotIndex = uint8(matrix.spots.length);
        require(
            spotIndex < MATRIX_SIZE,
            "Matrix is full, should have recycled"
        );

        // 1. Physically place the user in this matrix
        matrix.spots.push(user);

        if (spotIndex == 0 && matrix.currentUpline == address(0)) {
            matrix.currentUpline = _findGlobalUpline(upline, slot);
        }

        emit PlacedInGlobalMatrix(user, upline, slot, cycle, spotIndex + 1);

        bool hasJumped = false;

        // 2. ROUTING LOGIC (WITH ANTI-BOOMERANG PROTECTION)

        // RULE: Level 1 - Spot 1 (Index 0) Jumps to the 2nd Upline
        if (spotIndex == 0) {
            if (upline != owner) {
                address upline2 = _findGlobalUpline(upline, slot);
                uint256 u2Cycle = userMatrices[upline2][slot]
                    .currentGlobalCycle;

                // 🛑 ANTI-LOOP FIX: Check if upline2 is the user themselves!
                if (
                    upline2 != user &&
                    !_isUserInGlobalCycle(upline2, slot, u2Cycle, user)
                ) {
                    _placeInGlobalMatrix(user, upline2, slot);
                    hasJumped = true;
                }
            }
        }
        // RULE: Level 1 - Spot 2 (Index 1) Jumps to the 3rd Upline
        else if (spotIndex == 1) {
            if (upline != owner) {
                address upline2 = _findGlobalUpline(upline, slot);
                address upline3 = _findGlobalUpline(upline2, slot);
                uint256 u3Cycle = userMatrices[upline3][slot]
                    .currentGlobalCycle;

                // 🛑 ANTI-LOOP FIX: Try 3rd upline first, ensure it's not the user
                if (
                    upline3 != owner &&
                    upline3 != user &&
                    !_isUserInGlobalCycle(upline3, slot, u3Cycle, user)
                ) {
                    _placeInGlobalMatrix(user, upline3, slot);
                    hasJumped = true;
                }
                // 🛑 ANTI-LOOP FIX: Fallback to 2nd upline, ensure it's not the user
                else if (
                    upline2 != owner &&
                    upline2 != user &&
                    !_isUserInGlobalCycle(
                        upline2,
                        slot,
                        userMatrices[upline2][slot].currentGlobalCycle,
                        user
                    )
                ) {
                    _placeInGlobalMatrix(user, upline2, slot);
                    hasJumped = true;
                }
            }
        }
        // RULE: Level 3 Spill-down (Spots 7, 10, 13 / Index 6, 9, 12)
        else if (spotIndex == 6 || spotIndex == 9 || spotIndex == 12) {
            address downlineTarget = _peekQualifiedDirect(upline, slot);
            if (downlineTarget != address(0) && downlineTarget != user) {
                uint256 downCycle = userMatrices[downlineTarget][slot]
                    .currentGlobalCycle;

                if (
                    !_isUserInGlobalCycle(downlineTarget, slot, downCycle, user)
                ) {
                    // We are confirmed to jump! We must advance the Round-Robin state here.
                    _getQualifiedDirect(upline, slot);

                    _placeInGlobalMatrix(user, downlineTarget, slot);
                    hasJumped = true;
                }
            }
        }

        // 3. PAYOUT LOGIC: If a jump was blocked, the user stays here and this spot pays out!
        if (!hasJumped) {
            _processGlobalSpot(user, upline, slot, spotIndex, cycle);
        }
    }

    // 2. INFINITY MATRIX
    function _placeInLevelMatrix(
        address user,
        address upline,
        uint8 slot
    ) internal {
        uint256 cycle = userMatrices[upline][slot].currentLevelCycle;
        LevelCycle storage matrix = userMatrices[upline][slot].levelCycles[
            cycle
        ];

        uint8 spotIndex = 0;
        while (
            spotIndex < matrix.spots.length &&
            matrix.spots[spotIndex] != address(0)
        ) {
            spotIndex++;
        }
        require(spotIndex < MATRIX_SIZE, "Matrix is full");

        address physicalParent;
        if (spotIndex == 0 || spotIndex == 1) {
            physicalParent = upline; // Row 1: Direct child of the matrix owner
        } else {
            physicalParent = matrix.spots[(spotIndex - 2) / 2]; // Row 2 & 3: Child of a spillover parent
        }

        // 2. Bind the newly placed user to this physical parent
        uint256 userCycle = userMatrices[user][slot].currentLevelCycle;
        userMatrices[user][slot]
            .levelCycles[userCycle]
            .currentUpline = physicalParent;
        // 1. Physically place User
        _padAndPlaceLevel(upline, slot, user, spotIndex);
        emit PlacedInLevelMatrix(user, upline, slot, cycle, spotIndex + 1);

        address[50] memory modifiedQueue;
        uint8[1] memory qCount;
        qCount[0] = 0;

        modifiedQueue[qCount[0]++] = upline;

        // 2. TOP-DOWN SPILLOVER
        if (spotIndex >= 2 && spotIndex <= 5) {
            address l1Parent = matrix.spots[(spotIndex - 2) / 2];
            if (l1Parent != address(0)) {
                uint8 childIdx = (spotIndex % 2 == 0) ? 0 : 1;
                _padAndPlaceLevel(l1Parent, slot, user, childIdx);
                modifiedQueue[qCount[0]++] = l1Parent;
            }
        } else if (spotIndex >= 6 && spotIndex <= 13) {
            address directParent = matrix.spots[(spotIndex - 2) / 2];
            address grandParent = matrix.spots[(spotIndex - 6) / 4];

            if (grandParent != address(0)) {
                uint8 gpChildIdx = ((spotIndex - 6) % 4) + 2;
                _padAndPlaceLevel(grandParent, slot, user, gpChildIdx);
                modifiedQueue[qCount[0]++] = grandParent;
            }
            if (directParent != address(0)) {
                uint8 dpChildIdx = (spotIndex % 2 == 0) ? 0 : 1;
                _padAndPlaceLevel(directParent, slot, user, dpChildIdx);
                modifiedQueue[qCount[0]++] = directParent;
            }
        }

        // 3. BOTTOM-UP BUBBLING
        _bubbleUpLevel(user, upline, slot, spotIndex, modifiedQueue, qCount);

        // 4. Process Payouts FIRST
        _processLevelSpot(user, upline, slot, spotIndex, cycle);

        // 5. TRIGGER RECYCLE CHECKS AT THE VERY END
        for (uint8 i = 0; i < qCount[0]; i++) {
            _checkAndRecycleLevel(modifiedQueue[i], slot);
        }
    }

    function _bubbleUpLevel(
        address user,
        address currentUpline,
        uint8 slot,
        uint8 userIndex,
        address[50] memory modifiedQueue,
        uint8[1] memory qCount
    ) internal {
        // FIX: Removed || currentUpline == owner so bubbles can pass through User 1
        if (currentUpline == address(0)) return;

        uint256 cycle = userMatrices[currentUpline][slot].currentLevelCycle;
        address grandUpline = userMatrices[currentUpline][slot]
            .levelCycles[cycle]
            .currentUpline;

        if (grandUpline == address(0)) return;

        // Historical Search to prevent Detachment Bug
        uint256 targetCycle = userMatrices[grandUpline][slot].currentLevelCycle;
        int8 uplineIndex = -1;

        while (true) {
            uplineIndex = _findUserIndex(
                grandUpline,
                slot,
                targetCycle,
                currentUpline
            );
            if (uplineIndex != -1) break;
            if (targetCycle == 0) break;
            targetCycle--;
        }

        if (uplineIndex != -1) {
            uint8 targetIndex;

            if (userIndex == 0 || userIndex == 1) {
                targetIndex = uint8(2 * (uint8(uplineIndex) + 1) + userIndex);
            } else if (userIndex >= 2 && userIndex <= 5) {
                targetIndex = uint8(
                    4 * (uint8(uplineIndex) + 1) + 2 + (userIndex - 2)
                );
            } else if (userIndex >= 6 && userIndex <= 13) {
                targetIndex = uint8(
                    8 * (uint8(uplineIndex) + 1) + 6 + (userIndex - 6)
                );
            } else {
                return;
            }

            if (targetIndex < MATRIX_SIZE) {
                _padAndPlaceLevelAtCycle(
                    grandUpline,
                    slot,
                    targetCycle,
                    user,
                    targetIndex
                );

                if (qCount[0] < 50) {
                    modifiedQueue[qCount[0]++] = grandUpline;
                }

                _bubbleUpLevel(
                    user,
                    grandUpline,
                    slot,
                    targetIndex,
                    modifiedQueue,
                    qCount
                );
            }
        }
    }

    // --- INTERNAL CORE ROUTING LOGIC ---

    // 1. GLOBAL MATRIX (14-Spot BTitan Logic)
    function _processGlobalSpot(
        address user,
        address upline,
        uint8 slot,
        uint8 spotIndex,
        uint256 cycle
    ) internal {
        uint256 amount = slotPrices[slot];
        GlobalCycle storage matrix = userMatrices[upline][slot].globalCycles[
            cycle
        ];

        // 1st Spot (Index 0): Pays you's upline
        if (spotIndex == 0) {
            address target = _findGlobalUpline(upline, slot);
            // If the loop was broken, target is the user. Send to Treasury!
            if (target == user || target == address(0)) target = treasuryWallet;
            _sendDividends(target, user, amount, slot, "Global Spot 1", true);
        }
        // 2nd Spot (Index 1): Pays you's upline's upline
        else if (spotIndex == 1) {
            address u2 = _findGlobalUpline(upline, slot);
            address target = _findGlobalUpline(u2, slot);
            // If the loop was broken, target is the user. Send to Treasury!
            if (target == user || target == address(0)) target = treasuryWallet;
            _sendDividends(target, user, amount, slot, "Global Spot 2", true);
        }
        // 3rd & 6th Spot (Index 2, 5) AND 8th, 11th, 12th Spot (Index 7, 10, 11): Pays YOU
        else if (
            spotIndex == 2 ||
            spotIndex == 5 ||
            spotIndex == 7 ||
            spotIndex == 10 ||
            spotIndex == 11
        ) {
            _sendDividends(upline, user, amount, slot, "Global Base", true);
        }
        // 4th & 5th Spot (Index 3, 4): Upgrade Hold OR Pays YOU if cycle > 0
        else if (spotIndex == 3 || spotIndex == 4) {
            if (cycle == 0 && slot < LAST_SLOT && upline != owner) {
                matrix.upgradeHoldings += amount;
                emit FundsWithheld(
                    user,
                    upline,
                    slot,
                    amount,
                    "Global Upgrade Hold"
                );
                // Triggers upgrade when 2 payments are collected
                if (matrix.upgradeHoldings >= slotPrices[slot + 1]) {
                    _autoUpgrade(upline, slot + 1);
                    matrix.upgradeHoldings = 0;
                }
            } else {
                // Cycle 2+ or Max Slot: Pays YOU instantly
                // 🟢 FIX: Changed this string to "Global Base" to fix your income tracker
                _sendDividends(upline, user, amount, slot, "Global Base", true);
            }
        }
        // 7th, 10th, 13th Spot (Index 6, 9, 12): Pays to Qualified Direct Friend
        else if (spotIndex == 6 || spotIndex == 9 || spotIndex == 12) {
            address target = _getQualifiedDirect(upline, slot);
            if (target == address(0) || target == user) target = treasuryWallet;
            _sendDividends(
                target,
                user,
                amount,
                slot,
                "Global Direct Friend",
                true
            );
        }
        // 9th Spot (Index 8): Liquidity
        else if (spotIndex == 8) {
            _sendDividends(
                liquidityWallet,
                user,
                amount,
                slot,
                "Global Liquidity",
                true
            );
        }
        // 14th Spot (Index 13): Recycle
        else if (spotIndex == 13) {
            matrix.isCompleted = true;
            userMatrices[upline][slot].currentGlobalCycle++;

            address targetUpline;
            // Owner recycles under User 1
            if (upline == owner) {
                targetUpline = matrix.spots[0];
                if (targetUpline == address(0)) targetUpline = owner;
            } else {
                targetUpline = _findGlobalUpline(upline, slot);
            }

            userMatrices[upline][slot]
                .globalCycles[userMatrices[upline][slot].currentGlobalCycle]
                .currentUpline = targetUpline;

            // Final Anti-Loop protection for the physical placement
            if (targetUpline != upline) {
                _placeInGlobalMatrix(upline, targetUpline, slot);
            }

            emit MatrixRecycled(
                upline,
                slot,
                userMatrices[upline][slot].currentGlobalCycle,
                "TON Titan"
            );
        }
    }

    function _checkAndRecycleLevel(
        address targetMatrixOwner,
        uint8 slot
    ) internal {
        uint256 cycle = userMatrices[targetMatrixOwner][slot].currentLevelCycle;
        LevelCycle storage matrix = userMatrices[targetMatrixOwner][slot]
            .levelCycles[cycle];

        // 1. If already completed or not enough people, cancel.
        if (matrix.isCompleted || matrix.spots.length < MATRIX_SIZE) return;

        // 2. Scan for any empty gaps left by spillover jumps
        for (uint8 i = 0; i < MATRIX_SIZE; i++) {
            if (matrix.spots[i] == address(0)) return;
        }

        // 3. IF WE PASS THE CHECKS, THE MATRIX IS PERFECTLY FULL! Trigger Re-entry.
        matrix.isCompleted = true;
        userMatrices[targetMatrixOwner][slot].currentLevelCycle++;
        matrix.reentryHoldings = 0;

        address targetUpline;

        // 👑 Community Spill-Down for Owner
        if (targetMatrixOwner == owner) {
            targetUpline = matrix.spots[0];
            if (targetUpline == address(0)) targetUpline = owner;
        }
        // 👤 Normal follow-sponsor
        else {
            targetUpline = _findLevelUpline(targetMatrixOwner, slot);
        }

        _placeInLevelMatrix(targetMatrixOwner, targetUpline, slot);

        emit MatrixRecycled(
            targetMatrixOwner,
            slot,
            userMatrices[targetMatrixOwner][slot].currentLevelCycle,
            "TON Infinity"
        );
    }

    // 2. LEVEL MATRIX (Pyramid Logic 15/10/25 + 50%)
    function _processLevelSpot(
        address user,
        address upline,
        uint8 slot,
        uint8 spotIndex,
        uint256 cycle
    ) internal {
        uint256 amount = slotPrices[slot];

        // Base Percentages
        uint256 l1Amount = (amount * 15) / 100;
        uint256 l2Amount = (amount * 10) / 100;
        uint256 l3BaseAmount = (amount * 20) / 100;
        uint256 liqAmount = (amount * 5) / 100;
        uint256 bonusAmount = (amount * 50) / 100;

        // Determine which level gets the 50% Bonus based on the slot
        // Formula cycles: Slot 1 -> L1, Slot 2 -> L2, Slot 3 -> L3, Slot 4 -> L1...
        uint8 bonusTarget = ((slot - 1) % 3) + 1;

        // Get L1, L2, L3 Receivers from the binary tree
        (
            address l1Receiver,
            address l2Receiver,
            address l3Receiver
        ) = _getLevelReceivers(upline, slot, cycle, spotIndex);

        // --- RE-ENTRY CHECK FOR L3 ---
        // We must find out exactly what index the new user occupies in the L3 Receiver's matrix.
        int8 l3Index = -1;
        if (l3Receiver != address(0)) {
            uint256 l3Cycle = userMatrices[l3Receiver][slot].currentLevelCycle;
            while (true) {
                l3Index = _findLatestUserIndex(l3Receiver, slot, l3Cycle, user);
                if (l3Index != -1) break;
                if (l3Cycle == 0) break;
                l3Cycle--;
            }
        }

        // Spots 7, 9, 11, 13 are reserved for Re-entry (0-indexed array)
        bool isReentrySpot = (l3Index == 7 ||
            l3Index == 9 ||
            l3Index == 11 ||
            l3Index == 13);

        // --- DISTRIBUTE L1 ---
        if (l1Receiver != address(0)) {
            // Send Base
            _sendDividends(
                l1Receiver,
                user,
                l1Amount,
                slot,
                "Level 1 Base",
                false
            );

            // Send Bonus Separately if applicable
            if (bonusTarget == 1) {
                _sendDividends(
                    l1Receiver,
                    user,
                    bonusAmount,
                    slot,
                    "Direct Bonus L1",
                    false
                );
            }
        } else {
            uint256 l1Total = l1Amount + (bonusTarget == 1 ? bonusAmount : 0);
            _sendDividends(
                treasuryWallet,
                user,
                l1Total,
                slot,
                "Level 1 Treasury Fallback",
                false
            );
        }

        // --- DISTRIBUTE L2 ---
        if (l2Receiver != address(0)) {
            // Send Base
            _sendDividends(
                l2Receiver,
                user,
                l2Amount,
                slot,
                "Level 2 Base",
                false
            );

            // Send Bonus Separately if applicable
            if (bonusTarget == 2) {
                _sendDividends(
                    l2Receiver,
                    user,
                    bonusAmount,
                    slot,
                    "Direct Bonus L2",
                    false
                );
            }
        } else {
            uint256 l2Total = l2Amount + (bonusTarget == 2 ? bonusAmount : 0);
            _sendDividends(
                treasuryWallet,
                user,
                l2Total,
                slot,
                "Level 2 Treasury Fallback",
                false
            );
        }

        // --- DISTRIBUTE L3 & LIQUIDITY & REENTRY ---
        if (isReentrySpot) {
            // WITHHOLDING: Reserve 25% (20% L3 Base + 5% Liquidity) for the L3 Receiver's matrix re-entry
            LevelCycle storage l3Matrix = userMatrices[l3Receiver][slot]
                .levelCycles[userMatrices[l3Receiver][slot].currentLevelCycle];
            l3Matrix.reentryHoldings += (amount * 25) / 100;
            emit FundsWithheld(
                user,
                l3Receiver,
                slot,
                (amount * 25) / 100,
                "Level Reentry Hold"
            );

            // If L3 is owed the 50% Bonus on this slot, they STILL get it instantly!
            if (bonusTarget == 3) {
                _sendDividends(
                    l3Receiver,
                    user,
                    bonusAmount,
                    slot,
                    "Direct Bonus L3",
                    false
                );
            }
        } else {
            // NORMAL PAYOUT: For Spots 6, 8, 10, 12
            _sendDividends(
                royalPoolWallet,
                user,
                liqAmount,
                slot,
                "Level Royal Pool",
                false
            );
            if (!isDeploying) {
                dailyRoyaltyCollection[getCurrentDay()] += liqAmount;
            }

            if (l3Receiver != address(0)) {
                // Send Base
                _sendDividends(
                    l3Receiver,
                    user,
                    l3BaseAmount,
                    slot,
                    "Level 3 Base",
                    false
                );

                // Send Bonus Separately if applicable
                if (bonusTarget == 3) {
                    _sendDividends(
                        l3Receiver,
                        user,
                        bonusAmount,
                        slot,
                        "Direct Bonus L3",
                        false
                    );
                }
            } else {
                uint256 l3Total = l3BaseAmount +
                    (bonusTarget == 3 ? bonusAmount : 0);
                _sendDividends(
                    treasuryWallet,
                    user,
                    l3Total,
                    slot,
                    "Level 3 Treasury Fallback",
                    false
                );
            }
        }
    }

    // --- UPLINE SEARCH ALGORITHMS ---

    function _findGlobalUpline(
        address user,
        uint8 slot
    ) internal view returns (address) {
        address currentReferrer = users[user].referrer;

        while (currentReferrer != address(0) && currentReferrer != owner) {
            if (users[currentReferrer].activeGlobalSlots[slot]) {
                uint256 cycle = userMatrices[currentReferrer][slot]
                    .currentGlobalCycle;
                if (
                    userMatrices[currentReferrer][slot]
                        .globalCycles[cycle]
                        .spots
                        .length < MATRIX_SIZE
                ) {
                    return currentReferrer;
                }
            }
            currentReferrer = users[currentReferrer].referrer;
        }
        return owner;
    }

    function _findLevelUpline(
        address user,
        uint8 slot
    ) internal view returns (address) {
        address currentReferrer = users[user].referrer;

        while (currentReferrer != address(0) && currentReferrer != owner) {
            if (users[currentReferrer].activeLevelSlots[slot]) {
                uint256 cycle = userMatrices[currentReferrer][slot]
                    .currentLevelCycle;
                if (
                    userMatrices[currentReferrer][slot]
                        .levelCycles[cycle]
                        .spots
                        .length < MATRIX_SIZE
                ) {
                    return currentReferrer;
                }
            }
            currentReferrer = users[currentReferrer].referrer;
        }
        return owner;
    }

