    function _autoUpgrade(address user, uint8 newSlot) internal {
        // 1. Activate ONLY the Global Slot
        users[user].activeGlobalSlots[newSlot] = true;

        // 2. Place ONLY in the Global Matrix
        _placeInGlobalMatrix(user, _findGlobalUpline(user, newSlot), newSlot);

        // 🛑 Notice: No Level Matrix code here!
        emit AutoUpgraded(user, newSlot);
    }

    function _sendDividends(
        address receiver,
        address from,
        uint256 amount,
        uint8 slot,
        string memory earnType,
        bool isGlobal
    ) internal {
        if (amount == 0 || receiver == address(0)) return;

        address physicalPayoutAddress = receiver;
        if (isCompanyNode[receiver]) {
            require(companyWallet != address(0), "Company wallet not set");
            physicalPayoutAddress = companyWallet;
        }

        if (!isDeploying) {
            WTON_TOKEN.safeTransfer(physicalPayoutAddress, amount);
        }

        // Update Income Trackers
        if (
            receiver != liquidityWallet &&
            receiver != royalPoolWallet &&
            receiver != treasuryWallet
        ) {
            UserIncome storage income = users[receiver].income;
            income.totalEarned += amount;

            if (isGlobal) {
                if (
                    keccak256(bytes(earnType)) ==
                    keccak256(bytes("Global Base"))
                ) income.globalBaseEarned += amount;
                else income.globalSpillEarned += amount;
            } else {
                if (
                    keccak256(bytes(earnType)) ==
                    keccak256(bytes("Direct Bonus L1")) ||
                    keccak256(bytes(earnType)) ==
                    keccak256(bytes("Direct Bonus L2")) ||
                    keccak256(bytes(earnType)) ==
                    keccak256(bytes("Direct Bonus L3"))
                ) {
                    income.levelDirectBonus += amount;
                } else {
                    income.levelBaseEarned += amount;
                }
            }
        }

        emit EarningsSent(receiver, from, amount, slot, earnType);
    }

