    // 3. Main Frontend Function: Calculates colors for the Matrix Tree
    // 3. Main Frontend Function: Calculates colors for the Matrix Tree
    function getMatrixUIColors(
        address matrixOwner,
        uint8 slot,
        uint256 cycle,
        bool isGlobal
    )
        external
        view
        returns (
            address[] memory paddedSpots,
            uint8[] memory colorCodes,
            uint256[] memory spotUserIds
        )
    {
        address[] memory actualSpots;

        if (isGlobal) {
            actualSpots = userMatrices[matrixOwner][slot]
                .globalCycles[cycle]
                .spots;
        } else {
            actualSpots = userMatrices[matrixOwner][slot]
                .levelCycles[cycle]
                .spots;
        }

        colorCodes = new uint8[](MATRIX_SIZE);
        paddedSpots = new address[](MATRIX_SIZE);
        spotUserIds = new uint256[](MATRIX_SIZE);

        for (uint8 i = 0; i < MATRIX_SIZE; i++) {
            if (i < actualSpots.length && actualSpots[i] != address(0)) {
                address spotUser = actualSpots[i];
                paddedSpots[i] = spotUser;
                spotUserIds[i] = users[spotUser].id;

                address directSponsor = users[spotUser].referrer;

                // 1. OVERTAKE CHECK (Global "Ahead" Logic)
                bool isOvertaking = false;

                if (directSponsor != address(0)) {
                    uint8 spotUserMax = 0;
                    uint8 sponsorMax = 0;

                    // Find max active slot for the user sitting in the spot
                    for (uint8 s = 15; s >= 1; s--) {
                        bool isActive = isGlobal
                            ? users[spotUser].activeGlobalSlots[s]
                            : users[spotUser].activeLevelSlots[s];
                        if (isActive) {
                            spotUserMax = s;
                            break; // Found highest, stop looping
                        }
                    }

                    // Find max active slot for their direct sponsor
                    for (uint8 s = 15; s >= 1; s--) {
                        bool isActive = isGlobal
                            ? users[directSponsor].activeGlobalSlots[s]
                            : users[directSponsor].activeLevelSlots[s];
                        if (isActive) {
                            sponsorMax = s;
                            break; // Found highest, stop looping
                        }
                    }

                    // If the user's highest slot is strictly greater, they are an Overtaker
                    if (spotUserMax > sponsorMax) {
                        isOvertaking = true;
                    }
                }

                if (isOvertaking) {
                    colorCodes[i] = 4; // Orange (Overtaken/Ahead of Sponsor)
                }
                // 2. NORMAL COLOR LOGIC
                else {
                    if (directSponsor == matrixOwner) {
                        colorCodes[i] = 1; // Yellow (Normal Direct)
                    } else if (_isDownline(matrixOwner, spotUser)) {
                        colorCodes[i] = 3; // White (Downline/Team member)
                    } else {
                        colorCodes[i] = 2; // Green (Upline Overflow/Spillover)
                    }
                }
            } else {
                colorCodes[i] = 0; // Empty
                spotUserIds[i] = 0;
            }
        }

        return (paddedSpots, colorCodes, spotUserIds);
    }

    // ==========================================
    // --- ADMINISTRATIVE & UTILITY FUNCTIONS ---
    // ==========================================

    function setRoyalPoolWallet(address _newWallet) external onlyOwner {
        require(_newWallet != address(0), "Cannot be zero address");
        royalPoolWallet = _newWallet;
    }

    function setLiquidityWallet(address _newWallet) external onlyOwner {
        require(_newWallet != address(0), "Cannot be zero address");
        liquidityWallet = _newWallet;
    }

    function setTreasuryWallet(address _newWallet) external onlyOwner {
        require(_newWallet != address(0), "Cannot be zero address");
        treasuryWallet = _newWallet;
    }

    function rescueFunds(
        address tokenAddress,
        uint256 amount
    ) external onlyOwner {
        if (tokenAddress == address(0)) {
            // Rescue Native Coin (e.g., BNB, ETH, MATIC)
            (bool success, ) = payable(owner).call{value: amount}("");
            require(success, "Native token transfer failed");
        } else {
            IERC20(tokenAddress).transfer(owner, amount);
        }
    }

    function getUserIdByAddress(address user) external view returns (uint256) {
        return users[user].id;
    }

    function getAllActiveSlots(
        address user
    )
        external
        view
        returns (bool[] memory globalSlots, bool[] memory levelSlots)
    {
        globalSlots = new bool[](LAST_SLOT);
        levelSlots = new bool[](LAST_SLOT);

        for (uint8 i = 1; i <= LAST_SLOT; i++) {
            // Arrays are 0-indexed, but slots start at 1
            globalSlots[i - 1] = users[user].activeGlobalSlots[i];
            levelSlots[i - 1] = users[user].activeLevelSlots[i];
        }

        return (globalSlots, levelSlots);
    }

    function getMaxActivatedSlots(
        address user
    ) external view returns (uint8, uint8) {
        uint8 maxGlobal = _getMaxSlot(user, true);
        uint8 maxLevel = _getMaxSlot(user, false);

        return (maxGlobal, maxLevel); // Explicitly returning the values
    }

    function getSystemHoldingsInRange(
        uint256 startId,
        uint256 endId
    )
        external
        view
        returns (
            uint256 totalGlobalUpgradeHoldings,
            uint256 totalLevelReentryHoldings,
            uint256 combinedTotal
        )
    {
        require(startId > 0 && startId <= endId, "Invalid range");

        uint256 gHoldings = 0;
        uint256 lHoldings = 0;

        for (uint256 i = startId; i <= endId; i++) {
            if (i >= nextUserId) break; // Stop if we exceed registered users

            address userAddr = idToAddress[i];
            if (userAddr == address(0)) continue;

            for (uint8 slot = 1; slot <= 15; slot++) {
                // Get current cycle IDs for this user & slot
                (uint256 gCycle, uint256 lCycle) = this.getCurrentCycleIds(
                    userAddr,
                    slot
                );

                // 1. Add Global Matrix Upgrade Holdings
                if (users[userAddr].activeGlobalSlots[slot]) {
                    // We only need the 3rd returned variable (upgradeHoldings)
                    (, , uint256 upgradeHoldings, ) = this
                        .getGlobalMatrixCycleData(userAddr, slot, gCycle);
                    gHoldings += upgradeHoldings;
                }

                // 2. Add Level Matrix Reentry Holdings
                if (users[userAddr].activeLevelSlots[slot]) {
                    // We only need the 3rd returned variable (reentryHoldings)
                    (, , uint256 reentryHoldings, ) = this
                        .getLevelMatrixCycleData(userAddr, slot, lCycle);
                    lHoldings += reentryHoldings;
                }
            }
        }

        return (gHoldings, lHoldings, gHoldings + lHoldings);
    }
